import { useState, useEffect } from 'react';
import { 
  hrGetForms, hrGetFormDetails, // <-- Added this (assuming it exists in your api/index.js)
  hrCreateForm, hrUpdateForm, hrDeleteForm, 
  hrActivateForm, hrDeactivateForm, hrAddQuestion, hrDeleteQuestion 
} from '../../api/index.js';
import { Spinner, Modal, Input, Textarea, Btn, Badge, useToast } from '../../components/shared/index.jsx';

const FIELD_TYPES = ['score_1_4', 'boolean', 'decimal'];
const FIELD_LABELS = { score_1_4: 'Score 1-4', boolean: 'Yes / No', decimal: 'Decimal' };

export function HRFormsPage() {
  const toast = useToast();
  const [forms, setForms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [detailLoading, setDetailLoading] = useState(false); // New loading state for questions
  const [selectedForm, setSelected] = useState(null);
  const [showCreate, setShowCreate] = useState(false);
  const [showEdit, setShowEdit] = useState(false);
  const [showAddQ, setShowAddQ] = useState(false);
  const [formData, setFormData] = useState({ title: '', description: '' });
  const [qData, setQData] = useState({ questionText: '', fieldType: 'score_1_4', order: 0 });
  const [saving, setSaving] = useState(false);

  const load = async () => {
    setLoading(true);
    try {
      const data = await hrGetForms();
      setForms(Array.isArray(data) ? data : []);
    } catch { toast('Failed to load forms', 'error'); }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  // --- NEW: FETCH FULL DETAILS WHEN SELECTED ---
  const handleSelectForm = async (form) => {
    setSelected(form); // Set basic info immediately for UI responsiveness
    setDetailLoading(true);
    try {
      // If your API doesn't have hrGetFormDetails, you can try calling hrGetForms 
      // again and finding the specific item if the backend supports nesting there.
      // But usually, a dedicated 'get details' call is best:
      const fullForm = await hrGetFormDetails(form.formID);
      setSelected(fullForm);
    } catch (err) {
      console.error("Could not fetch questions:", err);
      // Fallback: stay with the basic form info
    } finally {
      setDetailLoading(false);
    }
  };

  const handleCreate = async () => {
    if (!formData.title.trim()) { toast('Title is required', 'error'); return; }
    setSaving(true);
    const res = await hrCreateForm(formData);
    setSaving(false);
    if (res.formID) { 
        toast('Form created'); 
        setShowCreate(false); 
        setFormData({ title: '', description: '' }); 
        load(); 
    } else toast('Failed to create form', 'error');
  };

  const handleUpdate = async () => {
    if (!formData.title.trim()) { toast('Title is required', 'error'); return; }
    setSaving(true);
    const res = await hrUpdateForm(selectedForm.formID, formData);
    setSaving(false);
    if (res.formID) { toast('Form updated'); setShowEdit(false); load(); }
    else toast('Failed to update form', 'error');
  };

  const handleAddQuestion = async () => {
    if (!qData.questionText) return toast('Question text is required', 'error');
    setSaving(true);
    try {
      const payload = {
        questionText: qData.questionText,
        fieldType: qData.fieldType,
        order: parseInt(qData.order) || 0
      };
      const res = await hrAddQuestion(selectedForm.formID, payload);
      toast('Question added successfully');
      setShowAddQ(false); 
      setQData({ questionText: '', fieldType: 'score_1_4', order: 0 });

      // Refresh details to get the new question list from DB
      handleSelectForm(selectedForm); 
      load(); // Update the question count badge in the sidebar
    } catch (err) {
      toast('Failed to add question', 'error');
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteQuestion = async (q) => {
    if (!window.confirm('Delete this question?')) return;
    try {
        await hrDeleteQuestion(q.questionID);
        toast('Question deleted');
        handleSelectForm(selectedForm); // Re-fetch
        load();
    } catch { toast('Delete failed', 'error'); }
  };

  // ... (handleDelete and handleToggleActive remain the same)

  return (
    <div style={{ maxWidth: 1280, margin: '0 auto', padding: '40px 32px 80px' }}>
      {/* ... Header remains same ... */}

      {loading ? (
        <div style={{ textAlign: 'center', padding: 80 }}><Spinner /></div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: '340px 1fr', gap: 24, alignItems: 'start' }}>

          {/* Forms list */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            {forms.map(form => (
              <div key={form.formID}
                onClick={() => handleSelectForm(form)} // Updated this line
                style={{
                  background: 'var(--white)', borderRadius: 20, padding: '20px 22px',
                  border: `2px solid ${selectedForm?.formID === form.formID ? 'var(--red)' : '#EAECF0'}`,
                  cursor: 'pointer', transition: 'all .2s',
                }}>
                {/* ... Inner content remains same ... */}
              </div>
            ))}
          </div>

          {/* Form detail / questions */}
          {selectedForm ? (
            <div style={{ background: 'var(--white)', borderRadius: 24, border: '1px solid #EAECF0', overflow: 'hidden' }}>
              <div style={{ padding: '24px 28px', borderBottom: '1px solid #F3F4F6', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <div>
                  <div style={{ fontSize: 18, fontWeight: 700, marginBottom: 4 }}>{selectedForm.title}</div>
                  {selectedForm.description && <p style={{ fontSize: 13, color: 'var(--gray-500)' }}>{selectedForm.description}</p>}
                </div>
                <Btn size="sm" onClick={() => setShowAddQ(true)}>Add Question</Btn>
              </div>

              <div style={{ padding: '16px 28px 28px' }}>
                {detailLoading ? (
                  <div style={{ padding: 40, textAlign: 'center' }}><Spinner /></div>
                ) : (!selectedForm.questions || selectedForm.questions.length === 0) ? (
                  <div style={{ textAlign: 'center', padding: '48px 24px', color: 'var(--gray-300)', fontSize: 13 }}>
                    No questions yet. Add your first question.
                  </div>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 12, marginTop: 8 }}>
                    {selectedForm.questions.map((q, i) => (
                      <div key={q.questionID} style={{
                        background: 'var(--gray-50)', borderRadius: 16, padding: '16px 20px',
                        display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 12,
                      }}>
                        <div style={{ flex: 1 }}>
                          <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--red)', textTransform: 'uppercase', marginBottom: 4 }}>
                            {FIELD_LABELS[q.fieldType]}
                          </div>
                          <div style={{ fontSize: 14, fontWeight: 600 }}>{i + 1}. {q.questionText}</div>
                        </div>
                        <Btn size="sm" variant="danger" onClick={() => handleDeleteQuestion(q)}>Delete</Btn>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div style={{ background: 'var(--white)', borderRadius: 24, border: '2px dashed var(--gray-300)', padding: '80px 32px', textAlign: 'center' }}>
               <p style={{ color: 'var(--gray-300)' }}>Select a form to manage its questions</p>
            </div>
          )}
        </div>
      )}
      {/* ... Modals remain the same ... */}
    </div>
  );
}
